import sys
from collections import deque

def main():
    # Read the 3x3 matrix
    matrix = []
    for _ in range(3):
        row = list(map(int, sys.stdin.readline().split()))
        matrix.append(row)

    threshold = 5
    capacity = 20

    # Check if any tank is below threshold
    has_below_threshold = any(matrix[i][j] < threshold for i in range(3) for j in range(3))

    if not has_below_threshold:
        # All tanks are above threshold, output as is
        for row in matrix:
            print(' '.join(map(str, row)))
        return

    # Use a queue to process tanks that need water
    queue = deque()

    # Initialize queue with all tanks below threshold
    for i in range(3):
        for j in range(3):
            if matrix[i][j] < threshold:
                queue.append((i, j))

    # Process tanks
    while queue:
        i, j = queue.popleft()

        if matrix[i][j] >= threshold:
            continue

        # Find the best source (maximum water) from adjacent tanks
        best_val = -1
        best_dir = -1  # 0=top, 1=right, 2=bottom, 3=left

        # Top
        if i > 0 and matrix[i-1][j] > threshold:
            if matrix[i-1][j] > best_val:
                best_val = matrix[i-1][j]
                best_dir = 0

        # Right
        if j < 2 and matrix[i][j+1] > threshold:
            if matrix[i][j+1] > best_val:
                best_val = matrix[i][j+1]
                best_dir = 1

        # Bottom
        if i < 2 and matrix[i+1][j] > threshold:
            if matrix[i+1][j] > best_val:
                best_val = matrix[i+1][j]
                best_dir = 2

        # Left
        if j > 0 and matrix[i][j-1] > threshold:
            if matrix[i][j-1] > best_val:
                best_val = matrix[i][j-1]
                best_dir = 3

        # If no source found, we can't fill this tank
        if best_val == -1:
            print("ERROR")
            return

        # Transfer water: 1 kilolitre from source to this tank
        source_i, source_j = -1, -1
        if best_dir == 0:
            source_i, source_j = i-1, j
        elif best_dir == 1:
            source_i, source_j = i, j+1
        elif best_dir == 2:
            source_i, source_j = i+1, j
        else:
            source_i, source_j = i, j-1

        # Transfer 1 kilolitre
        matrix[source_i][source_j] -= 1
        matrix[i][j] += 1

        # Check if source is now below threshold
        if matrix[source_i][source_j] < threshold:
            queue.append((source_i, source_j))

    # Check if all tanks are above threshold now
    for i in range(3):
        for j in range(3):
            if matrix[i][j] < threshold:
                print("ERROR")
                return

    # Output the final matrix
    for row in matrix:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    main()
